mapper.select:
SELECT 
FROM problem p FORCE INDEX (idx_problem_listing)
WHERE p.visibility = 'PUBLIC'
  AND p.status = 'ACTIVE'

  AND (p.slug LIKE CONCAT('%', #{q}, '%') ESCAPE '\\'
       OR p.title LIKE CONCAT('%', #{q}, '%') ESCAPE '\\')

AND p.difficulty = #{difficulty}
AND p.code_mode = #{codeMode}

  AND EXISTS (
      SELECT 1 FROM problem_language pl
      WHERE pl.problem_id = p.id AND pl.language_id = #{language}
  )



    AND JSON_CONTAINS(p.tags_json, JSON_QUOTE(#{tag}))



  AND (p.updated_at < #{cursorKey}
       OR (p.updated_at = #{cursorKey} AND p.id < UUID_TO_BIN(#{cursorId})))


  AND (p.updated_at > #{cursorKey}
       OR (p.updated_at = #{cursorKey} AND p.id > UUID_TO_BIN(#{cursorId})))


  AND (p.title > #{cursorKey}
       OR (p.title = #{cursorKey} AND p.id > UUID_TO_BIN(#{cursorId})))


  ORDER BY p.updated_at ASC, p.id ASC
  ORDER BY p.title ASC, p.id ASC
  ORDER BY p.updated_at DESC, p.id DESC

LIMIT #{limit}
